function resolveAuthHttpClient(getAuthHttpClient, controllerName) {
  if (!getAuthHttpClient) {
    throw new Error(`${controllerName} - no auth httpClient getter specified in config.`);
  }
  const httpClient = getAuthHttpClient();
  if (!httpClient) {
    throw new Error(`${controllerName} - no auth httpClient available.`);
  }
  return httpClient;
}

export { resolveAuthHttpClient };
